import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';
import {STABLE_MAKER_POLICY} from '../live-paper/stable-maker-paper-v2.mjs';import {stableMakerCodeIdentity,openStableMakerHost} from '../live-paper/stable-maker-host-v1.mjs';
import {collectFrozenPaperFiles} from '../live-paper/frozen-paper-graph.mjs';import {verifyChainedRows} from '../live-paper/stable-maker-replay-v2.mjs';import {atomicJson,payloadHash} from '../execution/ledger.mjs';
const sha=b=>createHash('sha256').update(b).digest('hex'),runtimeDir=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),workspace=process.cwd();
const marker=JSON.parse(fs.readFileSync(path.join(runtimeDir,'COLLECTOR_STOP')));if(marker.source!=='stable_broad_paper_deployment_20261005')throw Error('Deployment provenance missing');
const name='baal-stable-broad-20261005-v2-live',dir=path.join(runtimeDir,'stable-maker-cohorts',name);if(fs.existsSync(dir)||fs.existsSync(path.join(runtimeDir,'stable-maker-broad-active.json')))throw Error('Existing stable cohort must be preserved');
const source=fs.readFileSync(path.join(runtimeDir,'anonymous-trades.jsonl')),rows=verifyChainedRows(source),tape=rows.at(-1),cutoff=new Date().toISOString(),declaration=JSON.parse(fs.readFileSync('data/stable-broad-selection-20261005.json'));
if(declaration.candidates.length<2||declaration.candidates.length>16)throw Error('Insufficient screened broad scope');
const codeIdentity=stableMakerCodeIdentity(),bank={schemaVersion:1,mode:'stable_two_side_trade_tape_paper_v2',name,cutoff,entryExpiresAt:new Date(Date.parse(cutoff)+21600000).toISOString(),tournamentId:declaration.tournamentId,legs:declaration.candidates.map(x=>({marketId:x.marketId,exchangeId:x.exchangeId})),
 policy:STABLE_MAKER_POLICY,codeIdentity,tapePrefixBytes:source.length,tapePrefixHash:sha(source),tapePrefixSequence:tape?.sequence||0,tapePrefixTailHash:tape?.hash||'',
 protocolFileHash:sha(fs.readFileSync('data/stable-broad-selection-20261005.json')),selectionPricePrefix:declaration.source,selectionMode:declaration.selection,independentFromPriorWallet:true,
 counterfactualOnly:true,executionAuthority:false,competitionOrders:0,fees:0,profitabilityEstablished:false};
const files=collectFrozenPaperFiles(workspace,['live-paper/stable-maker-host-v1.mjs']),snapshot=payloadHash(files),frozenRoot=path.join(runtimeDir,'frozen-code',snapshot);
if(!fs.existsSync(frozenRoot)){fs.mkdirSync(frozenRoot,{recursive:true,mode:0o700});for(const [relative,hash]of Object.entries(files)){const target=path.resolve(frozenRoot,relative);if(!target.startsWith(path.resolve(frozenRoot)+path.sep))throw Error('Frozen scope');fs.mkdirSync(path.dirname(target),{recursive:true,mode:0o700});const b=fs.readFileSync(relative);if(sha(b)!==hash)throw Error('Source changed');fs.writeFileSync(target,b,{flag:'wx',mode:0o600});}fs.writeFileSync(path.join(frozenRoot,'manifest.json'),JSON.stringify({schemaVersion:1,files},null,2)+'\n',{flag:'wx',mode:0o600});}
const indexFile=path.join(runtimeDir,'frozen-code','index.json'),index=JSON.parse(fs.readFileSync(indexFile));index.banks[payloadHash(bank)]={snapshot};atomicJson(indexFile,index);
fs.mkdirSync(dir,{recursive:true,mode:0o700});atomicJson(path.join(dir,'bank.json'),bank);atomicJson(path.join(runtimeDir,'stable-maker-broad-active.json'),{schemaVersion:1,cohort:name,bankHash:payloadHash(bank)});
const h=openStableMakerHost({runtimeDir,activeFileName:'stable-maker-broad-active.json'}),s=h.status();if(s.wallets.YES.fills||s.wallets.NO.fills||s.wallets.YES.cash!=='100.000000'||s.wallets.NO.cash!=='100.000000')throw Error('Unexpected new wallet state');
fs.writeFileSync('data/stable-broad-live-bank-20261005.json',JSON.stringify({schemaVersion:1,at:cutoff,bankHash:payloadHash(bank),snapshot,bank,initialPaperState:{YES:{cash:s.wallets.YES.cash,fills:0},NO:{cash:s.wallets.NO.cash,fills:0}},originalWalletsReset:false,newServices:0,officialActivationChanged:false},null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({cohort:name,cutoff,bankHash:payloadHash(bank),frozenFiles:Object.keys(files).length,sourcePages:rows.length,networkRequests:0,competitionOrders:0}));
